mapper.select:
SELECT l.id,l.user_code, u.user_name, l.tenant_id, l.login_type, l.ip_address,
l.device_info, l.browser, l.os, l.login_time, l.status, l.message
FROM sys_login_log l
LEFT JOIN sys_user u ON l.user_code = u.user_code
WHERE 1=1
AND l.user_code = #{query.userCode}
AND l.login_type = #{query.loginType}
AND l.status = #{query.status}
ORDER BY l.login_time DESC
